#!/usr/bin/env bash
# TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
set -euo pipefail

if [ "$#" -ne 1 ]; then
    echo "Usage: $0 <48kHz-mono-16bit.wav>"
    exit 1
fi

INPUT="$1"
BASE="${INPUT%.*}"
DEMO="./build/host-macos/audio_effect_demo"

if [ ! -x "$DEMO" ]; then
    echo "Demo executable not found. Run:"
    echo "  cmake --preset host-macos"
    echo "  cmake --build --preset host-macos"
    exit 1
fi

"$DEMO" "$INPUT" "${BASE}_autotune_soft.wav" autotune-soft
"$DEMO" "$INPUT" "${BASE}_autotune_psola.wav" autotune
"$DEMO" "$INPUT" "${BASE}_autotune_hard.wav" autotune-hard
"$DEMO" "$INPUT" "${BASE}_autotune_legacy.wav" autotune-legacy

echo
echo "Generated four comparison files:"
echo "  ${BASE}_autotune_soft.wav"
echo "  ${BASE}_autotune_psola.wav"
echo "  ${BASE}_autotune_hard.wav"
echo "  ${BASE}_autotune_legacy.wav"
echo
echo "On macOS, listen in this order:"
echo "  afplay \"$INPUT\""
echo "  afplay \"${BASE}_autotune_soft.wav\""
echo "  afplay \"${BASE}_autotune_psola.wav\""
echo "  afplay \"${BASE}_autotune_hard.wav\""
echo "  afplay \"${BASE}_autotune_legacy.wav\""
